   75: /// Only _static_ data send in this packet !!!
   76: void QueryHandlers::HandleCreatureQuery(WorldSession& session, WorldPacket& recv_data)
   77: {
   78:     uint32 entry;
   79:     recv_data >> entry;
   80:     ObjectGuid guid;
   81:     recv_data >> guid;
   82: 
   83:     CreatureInfo const* ci = ObjectMgr::GetCreatureTemplate(entry);
   84:     if (ci)
   85:     {
   86:         int loc_idx = session.GetSessionDbLocaleIndex();
   87: 
   88:         char const* name = ci->Name;
   89:         char const* subName = ci->SubName;
   90:         sObjectMgr.GetCreatureLocaleStrings(entry, loc_idx, &name, &subName);
   91: 
   92:         DETAIL_LOG("WORLD: CMSG_CREATURE_QUERY '%s' - Entry: %u.", ci->Name, entry);
   93:         // guess size
   94:         WorldPacket data(SMSG_CREATURE_QUERY_RESPONSE, 100);
   95:         data << uint32(entry);                              // creature entry
   96:         data << name;
   97: 
   98:         for (uint8 i = 0; i < 7; ++i)
   99:         {
  100:             data << uint8(0);            // name2, name3, name4, always empty
  101:         }
  102: 
  103:         data << subName;
  104:         data << ci->IconName;                               // "Directions" for guard, string for Icons 2.3.0
  105:         data << uint32(ci->CreatureTypeFlags);                     // flags
  106:         data << uint32(0);                                  // unk
  107:         data << uint32(ci->CreatureType);                   // CreatureType.dbc
  108:         data << uint32(ci->Family);                         // CreatureFamily.dbc
  109:         data << uint32(ci->Rank);                           // Creature Rank (elite, boss, etc)
  110:         data << uint32(ci->KillCredit[0]);                  // new in 3.1, kill credit
  111:         data << uint32(ci->KillCredit[1]);                  // new in 3.1, kill credit
  112: 
  113:         for (int i = 0; i < MAX_CREATURE_MODEL; ++i)
  114:         {
  115:             data << uint32(ci->ModelId[i]);
  116:         }
  117: 
  118:         data << float(ci->HealthMultiplier);                  // health modifier
  119:         data << float(ci->PowerMultiplier);                   // power modifier
  120:         data << uint8(ci->RacialLeader);
  121:         for (uint32 i = 0; i < 6; ++i)
  122:         {
  123:             data << uint32(ci->QuestItems[i]);              // itemId[6], quest drop
  124:         }
  125:         data << uint32(ci->MovementTemplateId);                     // CreatureMovementInfo.dbc
  126:         data << uint32(0);                                  //unk
  127:         session.SendPacket(&data);
  128:         DEBUG_LOG("WORLD: Sent SMSG_CREATURE_QUERY_RESPONSE");
  129:     }
  130:     else
  131:     {
  132:         DEBUG_LOG("WORLD: CMSG_CREATURE_QUERY - Guid: %s Entry: %u NO CREATURE INFO!",
  133:                   guid.GetString().c_str(), entry);
  134:         WorldPacket data(SMSG_CREATURE_QUERY_RESPONSE, 4);
  135:         data << uint32(entry | 0x80000000);
  136:         session.SendPacket(&data);
  137:         DEBUG_LOG("WORLD: Sent SMSG_CREATURE_QUERY_RESPONSE");
  138:     }
  139: }
