  206: /**
  207:  * @brief Handles a corpse query and returns corpse or graveyard location data.
  208:  *
  209:  * @param recv_data The unused incoming packet.
  210:  */
  211: void QueryHandlers::HandleCorpseQuery(WorldSession& session, WorldPacket & /*recv_data*/)
  212: {
  213:     DETAIL_LOG("WORLD: Received opcode MSG_CORPSE_QUERY");
  214: 
  215:     Corpse* corpse = session.GetPlayer()->GetCorpse();
  216: 
  217:     if (!corpse)
  218:     {
  219:         WorldPacket data(MSG_CORPSE_QUERY, 1);
  220:         data << uint8(0);                                   // corpse not found
  221:         session.SendPacket(&data);
  222:         return;
  223:     }
  224: 
  225:     uint32 corpsemapid = corpse->GetMapId();
  226:     float x = corpse->Where().X();
  227:     float y = corpse->Where().Y();
  228:     float z = corpse->Where().Z();
  229:     int32 mapid = corpsemapid;
  230: 
  231:     // if corpse at different map
  232:     if (corpsemapid != session.GetPlayer()->GetMapId())
  233:     {
  234:         // search entrance map for proper show entrance
  235:         if (MapEntry const* corpseMapEntry = sMapStore.LookupEntry(corpsemapid))
  236:         {
  237:             if (corpseMapEntry->IsDungeon() && corpseMapEntry->CorpseMapID >= 0)
  238:             {
  239:                 // if corpse map have entrance
  240:                 if (TerrainInfo const* entranceMap = sTerrainMgr.LoadTerrain(corpseMapEntry->CorpseMapID))
  241:                 {
  242:                     mapid = corpseMapEntry->CorpseMapID;
  243:                     x = corpseMapEntry->Corpse_0;
  244:                     y = corpseMapEntry->Corpse_1;
  245:                     const auto entranceFloor = entranceMap->StaticFloor(x, y, MAX_HEIGHT);
  246:                     z = entranceFloor ? *entranceFloor : INVALID_HEIGHT;
  247:                 }
  248:             }
  249:         }
  250:     }
  251: 
  252:     WorldPacket data(MSG_CORPSE_QUERY, 1 + (6 * 4));
  253:     data << uint8(1);                                       // corpse found
  254:     data << int32(mapid);
  255:     data << float(x);
  256:     data << float(y);
  257:     data << float(z);
  258:     data << uint32(corpsemapid);
  259:     data << uint32(0);                                      // unknown
  260:     session.SendPacket(&data);
  261: }
