  439: void QueryHandlers::HandleQuestPOIQuery(WorldSession& session, WorldPacket& recv_data)
  440: {
  441:     uint32 count;
  442:     recv_data >> count;                                     // quest count, max=25
  443: 
  444:     if (count > MAX_QUEST_LOG_SIZE)
  445:     {
  446:         recv_data.rpos(recv_data.wpos());                   // set to end to avoid warnings spam
  447:         return;
  448:     }
  449: 
  450:     WorldPacket data(SMSG_QUEST_POI_QUERY_RESPONSE, 4 + (4 + 4)*count);
  451:     data << uint32(count);                                  // count
  452: 
  453:     for (uint32 i = 0; i < count; ++i)
  454:     {
  455:         uint32 questId;
  456:         recv_data >> questId;                               // quest id
  457: 
  458:         bool questOk = false;
  459: 
  460:         uint16 questSlot = session.GetPlayer()->FindQuestSlot(questId);
  461: 
  462:         if (questSlot != MAX_QUEST_LOG_SIZE)
  463:         {
  464:             questOk = session.GetPlayer()->GetQuestSlotQuestId(questSlot) == questId;
  465:         }
  466: 
  467:         if (questOk)
  468:         {
  469:             QuestPOIVector const* POI = sObjectMgr.GetQuestPOIVector(questId);
  470: 
  471:             if (POI)
  472:             {
  473:                 data << uint32(questId);                    // quest ID
  474:                 data << uint32(POI->size());                // POI count
  475: 
  476:                 for (QuestPOIVector::const_iterator itr = POI->begin(); itr != POI->end(); ++itr)
  477:                 {
  478:                     data << uint32(itr->PoiId);             // POI index
  479:                     data << int32(itr->ObjectiveIndex);     // objective index
  480:                     data << uint32(itr->MapId);             // mapid
  481:                     data << uint32(itr->MapAreaId);         // world map area id
  482:                     data << uint32(itr->FloorId);           // floor id
  483:                     data << uint32(itr->Unk3);              // unknown
  484:                     data << uint32(itr->Unk4);              // unknown
  485:                     data << uint32(itr->points.size());     // POI points count
  486: 
  487:                     for (std::vector<QuestPOIPoint>::const_iterator itr2 = itr->points.begin(); itr2 != itr->points.end(); ++itr2)
  488:                     {
  489:                         data << int32(itr2->x);             // POI point x
  490:                         data << int32(itr2->y);             // POI point y
  491:                     }
  492:                 }
  493:             }
  494:             else
  495:             {
  496:                 data << uint32(questId);                    // quest ID
  497:                 data << uint32(0);                          // POI count
  498:             }
  499:         }
  500:         else
  501:         {
  502:             data << uint32(questId);                        // quest ID
  503:             data << uint32(0);                              // POI count
  504:         }
  505:     }
  506: 
  507:     session.SendPacket(&data);
  508: }
